stage.script:
const k = kit3d({ grid: 18, fov: 40 });
const C = { orange: 0xff9c3a, gold: 0xffcc66, sky: 0x66ccff, green: 0x66dd88, lilac: 0xcc99ff, glass: 0xaabbdd };
const H = 4.4;
function tower(x, z, orbColor) {
  const g = new THREE.Group(); g.position.set(x, 0, z);
  const glassMat = new THREE.MeshPhysicalMaterial({ color: C.glass, transparent: true, opacity: 0.12, roughness: 0.1, depthWrite: false });
  const glass = new THREE.Mesh(new THREE.BoxGeometry(1.3, H, 1.3), glassMat); glass.position.y = H / 2; g.add(glass);
  const edgeMat = new THREE.LineBasicMaterial({ color: 0xc8d4ff, transparent: true, opacity: 0.6 });
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(1.3, H, 1.3)), edgeMat); edges.position.y = H / 2; g.add(edges);
  const orbMat = new THREE.MeshStandardMaterial({ color: orbColor, emissive: orbColor, emissiveIntensity: 0.35, roughness: 0.3, transparent: true });
  const orb = new THREE.Mesh(new THREE.SphereGeometry(0.45, 32, 20), orbMat); orb.position.y = H + 0.75; g.add(orb);
  function slab(color) { const m = new THREE.Mesh(new THREE.BoxGeometry(1.08, 1, 1.08), new THREE.MeshStandardMaterial({ color, roughness: 0.5, transparent: true })); g.add(m); return m; }
  return { g, orb, glassMat, edgeMat, orbMat, slab, x, z };
}
function setSlab(m, base, h, op) { m.visible = h > 0.01 && op > 0.01; m.scale.y = Math.max(h, 0.001); m.position.y = base + h / 2; m.material.opacity = op; }
function setTower(T, s, op) { T.g.scale.setScalar(Math.max(s, 0.001)); T.g.visible = s > 0.01; T.glassMat.opacity = 0.12 * op; T.edgeMat.opacity = 0.6 * op; T.orbMat.opacity = op; }

const main = tower(-4.5, 0, C.orange); k.add('main', main.g);
const mainBase = main.slab(C.orange), mainSum = main.slab(C.green);
const subPos = [[1.5, 0], [-0.6, -3], [3.6, -3]];
const subs = subPos.map(([x, z], i) => { const T = tower(x, z, C.lilac); k.add('sub' + i, T.g); T.prompt = T.slab(C.gold); T.work = T.slab(C.sky); return T; });

const code = new THREE.Group(); code.position.set(6.4, 0, -0.5); k.add('code', code);
const fileMat = new THREE.MeshStandardMaterial({ color: 0x8899bb, roughness: 0.6 });
for (let i = 0; i < 4; i++) for (let j = 0; j < 5; j++) for (let l = 0; l < (1 + ((i * 7 + j * 3) % 3)); l++) {
  const f = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.3, 0.55), fileMat); f.position.set((i - 1.5) * 0.6, 0.15 + l * 0.34, (j - 2) * 0.75); code.add(f);
}

function packet(color, size) { const m = new THREE.Mesh(new THREE.BoxGeometry(size, size, size), new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.5 })); m.visible = false; k.scene.add(m); return m; }
const flights = [];
function fly(mesh, from, to, start, dur, arc) { flights.push({ mesh, from: new THREE.Vector3(...from), to: new THREE.Vector3(...to), start, dur, arc }); }
const orbAt = (T) => [T.x, H + 0.75, T.z];
const topAt = (T) => [T.x, H + 0.2, T.z];
fly(packet(C.gold, 0.32), orbAt(main), orbAt(subs[0]), B[1] + 1.5, 2.5, 1.5);
fly(packet(C.gold, 0.32), orbAt(main), orbAt(subs[1]), B[3] + 0.8, 2.2, 1.5);
fly(packet(C.gold, 0.32), orbAt(main), orbAt(subs[2]), B[3] + 1.0, 2.2, 1.8);
for (let i = 0; i < 9; i++) fly(packet(C.sky, 0.26), [6.4 + ((i % 3) - 1) * 0.5, 1, ((i * 5) % 5 - 2) * 0.6 - 0.5], topAt(subs[0]), B[2] + 0.4 + i * 0.7, 1.4, 1.8);
for (let s = 1; s <= 2; s++) for (let i = 0; i < 5; i++) fly(packet(C.sky, 0.26), [6.4, 1, -1.5], topAt(subs[s]), B[3] + 3 + i * 0.75 + s * 0.3, 1.3, 1.6);
subs.forEach((T, i) => fly(packet(C.green, 0.36), orbAt(T), orbAt(main), B[4] + 0.6 + i * 0.6, 2.6, 2));

const lMain = k.label('Main agent', 'orange');
const lSub = k.label('Subagent: fresh context', 'lilac');
const lCode = k.label('Codebase', 'sky');
const lSum = k.label('Only the summary', 'green');
const lCtx = k.label('Context window', 'peri');
const lPar = k.label('Each in its own context', 'lilac');

function render(t) {
  k.shots(t, [
    { pos: [-1.5, 6, 12], look: [-3, 2.4, 0] },
    { pos: [-0.5, 6.5, 13], look: [-1.5, 2.6, 0] },
    { pos: [2, 6.5, 13.5], look: [1, 2.4, 0] },
    { pos: [0.5, 7.5, 15.5], look: [0.5, 2.6, -1.2] },
    { pos: [-0.5, 7.5, 15], look: [-0.8, 2.6, -1] },
    { pos: [-3, 6.5, 12], look: [-2.5, 2.4, 0] }
  ]);
  const mh = 1.5 * p(t, 0.6, 5.5);
  setTower(main, p(t, 0, 0.8), 1);
  setSlab(mainBase, 0.05, mh, 0.9);
  const sumH = 0.12 * p(t, B[4] + 2.6, B[4] + 3.4) + 0.12 * p(t, B[4] + 3.2, B[4] + 4.0) + 0.12 * p(t, B[4] + 3.8, B[4] + 4.6);
  setSlab(mainSum, 0.05 + mh, sumH, 0.95);
  const fade = 1 - p(t, B[4] + 4.5, B[4] + 6.5);
  subs.forEach((T, i) => {
    const born = i === 0 ? B[1] + 0.3 : B[3] + 0.2 + i * 0.2;
    const s = p(t, born, born + 1);
    setTower(T, s * (0.6 + 0.4 * fade), fade);
    const pr = 0.18 * p(t, i === 0 ? B[1] + 3.8 : B[3] + 2.8, i === 0 ? B[1] + 4.4 : B[3] + 3.3);
    const wk = i === 0 ? 2.9 * p(t, B[2] + 1.5, B[2] + 7.8) : 2.2 * p(t, B[3] + 4, B[3] + 7);
    setSlab(T.prompt, 0.05, pr, 0.95 * fade);
    setSlab(T.work, 0.05 + pr, wk, 0.85 * fade);
  });
  code.visible = t > B[1] + 0.5; code.scale.setScalar(p(t, B[1] + 0.5, B[1] + 1.8) || 0.001);
  const v = new THREE.Vector3();
  for (const f of flights) {
    const u = (t - f.start) / f.dur;
    if (u <= 0 || u >= 1) { f.mesh.visible = false; continue; }
    const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    v.lerpVectors(f.from, f.to, e); v.y += Math.sin(Math.PI * e) * f.arc;
    f.mesh.position.copy(v); f.mesh.rotation.set(t * 2, t * 1.5, 0); f.mesh.visible = true;
  }
  if (t < B[4] || t >= B[5]) lMain.at(main.orb, 1);
  if (t < B[1]) lCtx.at([main.x, 0.4 + mh, main.z + 0.7], p(t, 1, 2));
  if (t >= B[1] + 1 && t < B[3]) lSub.at(subs[0].orb, p(t, B[1] + 1, B[1] + 1.8));
  if (t >= B[2] && t < B[3]) lCode.at(code, 1);
  if (t >= B[3] + 1.5 && t < B[4]) lPar.at(subs[2].orb, p(t, B[3] + 1.5, B[3] + 2.3));
  if (t >= B[4] + 1 && t < B[5]) lSum.at(main.orb, 1);
  if (t >= B[5]) lSum.at([main.x + 0.65, 0.05 + mh + sumH, main.z + 0.65], p(t, B[5], B[5] + 1));
  k.draw(t);
}
